#!/bin/sh
compression_menu(){ while :; do c=$(ui_menu 'Compression tools' 'Compression defaults, tests, and archive helpers.' install 'Install compression bundle' default 'Choose default compressor' tar 'Create archive' extract 'Extract archive' benchmark 'Benchmark compressors' config 'Configure environment defaults' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in install) pkg_install tar gzip xz zstd zip unzip p7zip pigz 2>/dev/null || true;; default) x=$(ui_menu Compressor 'Select compressor.' gzip 'gzip - universal' xz 'xz - compact' zstd 'zstd - fast' pigz 'parallel gzip') || continue; replace_block "$CURRENT_HOME/.profile" compression "export ISH_AOK_COMPRESSOR='$x'";; tar) src=$(ui_input Archive 'Source path' .) || continue; out=$(ui_input Archive 'Output archive' archive.tar.zst) || continue; case $out in *.tar.gz|*.tgz) run_capture Archive tar -czf "$out" "$src";; *.tar.xz) run_capture Archive tar -cJf "$out" "$src";; *.tar.zst) run_capture Archive sh -c "tar -cf - \"$src\" | zstd -T0 -o \"$out\"";; *) run_capture Archive tar -cf "$out" "$src";; esac;; extract) a=$(ui_input Extract 'Archive path' '') || continue; d=$(ui_input Extract 'Destination' .) || continue; mkdir -p "$d"; run_capture Extract tar -xf "$a" -C "$d";; benchmark) f=$(ui_input Benchmark 'Input file' /etc/services) || continue; { for x in gzip xz zstd pigz; do have "$x" || continue; printf '\n== %s ==\n' "$x"; time sh -c "$x -c \"$f\" >\"$TMP_DIR/$x.out\""; wc -c "$TMP_DIR/$x.out"; done; } >"$TMP_DIR/cbench" 2>&1; ui_text Benchmark "$(cat "$TMP_DIR/cbench")";; config) edit_file "$CURRENT_HOME/.profile";; back) return;; esac; done; }
